from AlgorithmImports import *

class PrivateLotStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_closes = RollingWindow[float](101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        present_symbols = set(data.Bars.Keys)

        for symbol in self.symbols.values():
            if symbol in present_symbols:
                bar = data.Bars[symbol]

                if symbol == self.spy:
                    self.spy_sma.Update(bar.EndTime, bar.Close)
                    self.spy_closes.Add(bar.Close)

                elif symbol == self.aapl:
                    self.aapl_rsi.Update(bar.EndTime, bar.Close)

                    if self.aapl_previous_close is not None:
                        if bar.Close < self.aapl_previous_close:
                            self.aapl_red_streak += 1
                        else:
                            self.aapl_red_streak = 0

                    self.aapl_previous_close = bar.Close

        if any(symbol not in present_symbols for symbol in self.symbols.values()):
            return

        spy_ready = self.spy_sma.IsReady and self.spy_closes.IsReady
        aapl_ready = self.aapl_rsi.IsReady and self.aapl_previous_close is not None

        spy_buy_cross = False
        spy_sell_cross = False

        if spy_ready:
            today_close = self.spy_closes[0]
            yesterday_close = self.spy_closes[1]
            today_sma = self.spy_sma.Current.Value
            yesterday_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

            spy_buy_cross = yesterday_close <= yesterday_sma and today_close > today_sma
            spy_sell_cross = yesterday_close >= yesterday_sma and today_close < today_sma

        # Sells before buys.
        if self.strategy_a_shares > 0 and spy_sell_cross:
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and aapl_ready and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_buy_cross:
            quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) / data.Bars[self.spy].Close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and aapl_ready and self.aapl_red_streak >= 3:
            aapl_close = data.Bars[self.aapl].Close
            if self.Portfolio.Cash >= 20_000:
                quantity = int(20_000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_shares = quantity
