from AlgorithmImports import *


class PrivateLotStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.close_windows = {
            ticker: RollingWindow[float](101 if ticker == "SPY" else 4)
            for ticker in self.symbols
        }

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, slice: Slice):
        # Keep market-state calculations running whenever an individual bar exists.
        for ticker, symbol in self.symbols.items():
            if slice.Bars.ContainsKey(symbol):
                bar = slice.Bars[symbol]
                self.close_windows[ticker].Add(float(bar.Close))

                if ticker == "AAPL":
                    self.aapl_rsi.Update(bar.EndTime, bar.Close)

        # No rule evaluation unless every subscribed ticker has today's bar.
        if any(not slice.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        spy_window = self.close_windows["SPY"]
        aapl_window = self.close_windows["AAPL"]

        # Do not trade until every indicator or rolling window used by a rule is ready.
        if not spy_window.IsReady or not aapl_window.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = float(slice.Bars[self.spy].Close)
        aapl_close = float(slice.Bars[self.aapl].Close)

        current_spy_sma = sum(spy_window[i] for i in range(100)) / 100.0
        previous_spy_sma = sum(spy_window[i] for i in range(1, 101)) / 100.0
        previous_spy_close = spy_window[1]

        spy_crossed_above_sma = (
            previous_spy_close <= previous_spy_sma
            and spy_close > current_spy_sma
        )
        spy_crossed_below_sma = (
            previous_spy_close >= previous_spy_sma
            and spy_close < current_spy_sma
        )

        aapl_red_three_days = (
            aapl_window[0] < aapl_window[1]
            and aapl_window[1] < aapl_window[2]
            and aapl_window[2] < aapl_window[3]
        )
        aapl_rsi_above_60 = self.aapl_rsi.Current.Value > 60

        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and spy_crossed_below_sma:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and aapl_rsi_above_60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crossed_above_sma:
            quantity = int((0.40 * self.Portfolio.TotalPortfolioValue) // spy_close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and aapl_red_three_days:
